```csharp
public static int MinStepsToExit(char[][] grid)
{
    int rows = grid.Length;
    int cols = grid[0].Length;

    int playerRow = -1;
    int playerCol = -1;

    // Find the player's position
    for (int row = 0; row < rows; row++)
    {
        for (int col = 0; col < cols; col++)
        {
            if (grid[row][col] == 'P')
            {
                playerRow = row;
                playerCol = col;
                break;
            }
        }
        if (playerRow != -1) break;
    }

    // Perform breadth-first search to find the exit
    Queue<(int, int, int)> queue = new Queue<(int, int, int)>();
    queue.Enqueue((playerRow, playerCol, 0));

    bool[,] visited = new bool[rows, cols];
    visited[playerRow, playerCol] = true;

    int[] dr = { -1, 1, 0, 0 };
    int[] dc = { 0, 0, -1, 1 };

    while (queue.Count > 0)
    {
        var (r, c, steps) = queue.Dequeue();

        if (grid[r][c] == 'X')
        {
            return steps;
        }

        for (int i = 0; i < 4; i++)
        {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] != 'E' && !visited[nr, nc])
            {
                queue.Enqueue((nr, nc, steps + 1));
                visited[nr, nc] = true;
            }
        }
    }

    return -1; // If the exit is unreachable
}
```

This solution first finds the player's position in the grid and then performs a breadth-first search to find the exit, keeping track of the minimum number of steps required to reach the exit. If the exit is reachable, the function returns the minimum number of steps; otherwise, it returns -1 to indicate that the exit is unreachable.

